func bodyFingerprint(r *http.Request) (string, error) {
	raw, err := io.ReadAll(io.LimitReader(r.Body, maxBodyBytes))
	if err != nil {
		return "", fmt.Errorf("%w: read body: %v", payment.ErrInvalidInput, err)
	}
	r.Body = io.NopCloser(bytes.NewReader(raw))
	return hash(r.URL.Path + "|" + string(canonicalizeBody(raw))), nil
}

func canonicalizeBody(raw []byte) []byte {
	var val any
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	if err := dec.Decode(&val); err != nil {
		return raw
	}
	if _, err := dec.Token(); err != io.EOF {
		return raw
	}
	canonicalVal := normalizeValue(val, "")
	canon, err := json.Marshal(canonicalVal)
	if err != nil {
		return raw
	}
	return canon
}

func normalizeValue(v any, key string) any {
	switch val := v.(type) {
	case map[string]any:
		res := make(map[string]any, len(val))
		for k, child := range val {
			res[k] = normalizeValue(child, k)
		}
		return res
	case []any:
		res := make([]any, len(val))
		for i, child := range val {
			res[i] = normalizeValue(child, "")
		}
		return res
	case string:
		switch strings.ToLower(key) {
		case "currency":
			return strings.ToUpper(strings.TrimSpace(val))
		case "amount":
			return normalizeAmount(val)
		default:
			return val
		}
	case json.Number:
		if strings.ToLower(key) == "amount" {
			return normalizeAmount(val.String())
		}
		return val
	default:
		return val
	}
}

func normalizeAmount(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return s
	}
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = strings.TrimPrefix(s, "-")
	}
	intPart, frac, hasDot := strings.Cut(s, ".")
	if intPart == "" || !isDigits(intPart) {
		return s
	}
	if hasDot {
		if frac == "" || !isDigits(frac) {
			return s
		}
		frac = strings.TrimRight(frac, "0")
	}
	intPart = strings.TrimLeft(intPart, "0")
	if intPart == "" {
		intPart = "0"
	}
	res := intPart
	if frac != "" {
		res += "." + frac
	}
	if neg && (intPart != "0" || frac != "") {
		res = "-" + res
	}
	return res
}

func isDigits(s string) bool {
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

