 73	// bodyFingerprint hashes the request path and canonicalized body, then restores
 74	// the raw body so the handler can decode it.
 75	func bodyFingerprint(r *http.Request) (string, error) {
 76		raw, err := io.ReadAll(io.LimitReader(r.Body, maxBodyBytes))
 77		if err != nil {
 78			return "", fmt.Errorf("%w: read body: %v", payment.ErrInvalidInput, err)
 79		}
 80		r.Body = io.NopCloser(bytes.NewReader(raw))
 81		return hash(r.URL.Path + "|" + string(canonicalizeBody(raw))), nil
 82	}
 83	
 84	func canonicalizeBody(raw []byte) []byte {
 85		var val any
 86		dec := json.NewDecoder(bytes.NewReader(raw))
 87		dec.UseNumber()
 88		if err := dec.Decode(&val); err != nil {
 89			return raw
 90		}
 91		if _, err := dec.Token(); err != io.EOF {
 92			return raw
 93		}
 94		canonicalVal := normalizeValue(val, "")
 95		canon, err := json.Marshal(canonicalVal)
 96		if err != nil {
 97			return raw
 98		}
 99		return canon
100	}
