102	func normalizeValue(v any, key string) any {
103		switch val := v.(type) {
104		case map[string]any:
105			res := make(map[string]any, len(val))
106			for k, child := range val {
107				res[k] = normalizeValue(child, k)
108			}
109			return res
110		case []any:
111			res := make([]any, len(val))
112			for i, child := range val {
113				res[i] = normalizeValue(child, "")
114			}
115			return res
116		case string:
117			switch strings.ToLower(key) {
118			case "currency":
119				return strings.ToUpper(strings.TrimSpace(val))
120			case "amount":
121				return normalizeAmount(val)
122			default:
123				return val
124			}
125		case json.Number:
126			if strings.ToLower(key) == "amount" {
127				return normalizeAmount(val.String())
128			}
129			return val
130		default:
131			return val
132		}
133	}
