135	func normalizeAmount(s string) string {
136		s = strings.TrimSpace(s)
137		if s == "" {
138			return s
139		}
140		neg := false
141		if strings.HasPrefix(s, "-") {
142			neg = true
143			s = strings.TrimPrefix(s, "-")
144		}
145		intPart, frac, hasDot := strings.Cut(s, ".")
146		if intPart == "" || !isDigits(intPart) {
147			return s
148		}
149		if hasDot {
150			if frac == "" || !isDigits(frac) {
151				return s
152			}
153			frac = strings.TrimRight(frac, "0")
154		}
155		intPart = strings.TrimLeft(intPart, "0")
156		if intPart == "" {
157			intPart = "0"
158		}
159		res := intPart
160		if frac != "" {
161			res += "." + frac
162		}
163		if neg && (intPart != "0" || frac != "") {
164			res = "-" + res
165		}
166		return res
167	}
168	
169	func isDigits(s string) bool {
170		for _, r := range s {
171			if r < '0' || r > '9' {
172				return false
173			}
174		}
175		return true
176	}
